import {esc,state,currentProfile,listProfiles} from '../../lib/store.js';
import {localCounts} from '../../lib/privacy.js';
import {DEFAULT_UI_TEXT} from '../../data/seed.js';
import {button,input,area} from '../pixel/primitives.js';

export function welcome(){return `<main class="profile-welcome"><section class="profile-welcome-box"><div class="eyebrow">LOCAL-FIRST PERSONAL OS</div><h1>WELCOME TO DOUBLE'S HOME</h1><p class="profile-promise">YOUR DATA STAYS ON THIS DEVICE.</p><p>创建一个仅存在于当前浏览器的本地档案。无需邮箱、密码或远程账号。</p><form data-form="profile-create">${input('displayName','DISPLAY NAME（可选）','','text','maxlength="48" placeholder="Guest"')}<button class="button primary">CREATE LOCAL PROFILE</button></form><details><summary>PRIVACY / LOCAL DATA</summary><p>个人记录由当前应用保存在此浏览器中，不会通过正常运行上传给 GitHub 或网站作者。GitHub 只托管程序、公共素材和公共新闻数据。</p></details></section></main>`}
export function profileSwitcher(){const active=currentProfile();return `<p class="eyebrow">CURRENT PROFILE</p><div class="profile-list">${listProfiles().map(p=>`<button class="profile-choice ${p.profileId===active?.profileId?'active':''}" data-action="profile-switch" data-id="${esc(p.profileId)}"><b>${esc(p.displayName)}</b><small>${p.profileId===active?.profileId?'ACTIVE · LOCAL ONLY':'SWITCH PROFILE'}</small></button>`).join('')}</div>${button('＋ NEW LOCAL PROFILE','profile-new','','primary')}`}
export function privacySettings(){const p=currentProfile(),c=localCounts();return `<div class="privacy-settings"><div class="profile-status"><div><span>当前用户</span><b>${esc(p?.displayName||'—')}</b></div><div><span>存储方式</span><b>仅本地</b></div><div><span>任务</span><b>${c.tasks} 条记录</b></div><div><span>专注记录</span><b>${c.focus} 条记录</b></div><div><span>翻译记录</span><b>${c.translation} 条记录</b></div><div><span>日记</span><b>${c.diary} 条记录</b></div><div><span>财务记录</span><b>${c.finance} 条记录</b></div><div><span>研究资料</span><b>${c.research} 条记录</b></div><div><span>本地文件</span><b>${c.files} 个本地文件引用</b></div><div><span>最近备份</span><b>${p?.lastBackup?new Date(p.lastBackup).toLocaleString():'从未备份'}</b></div></div><div class="notice"><b>你的数据保存在这里。</b><br>double's home 会将个人记录保存在当前浏览器本地。当前应用不会把任务、笔记、翻译记录、日记、财务记录或专注历史发送给开发者。GitHub 仅用于托管应用代码和公开资源。</div><div class="actions">${button('导出我的数据','export','','primary')}${button('导入备份','backup-pick')}<input id="backup-picker" type="file" accept="application/json,.json" hidden>${button('申请持久化存储','persist-storage')}${button('删除我的本地数据','profile-delete','','danger')}</div><p id="storage-estimate" class="micro muted">申请持久化存储后，系统才会估算当前存储使用情况。</p></div>`}
export function personalUiText(){const value=state.uiText||DEFAULT_UI_TEXT;return `<h3>PERSONAL UI TEXT</h3><form data-form="ui-text">${area('sidebarMotto','SIDEBAR MOTTO',value.sidebarMotto||DEFAULT_UI_TEXT.sidebarMotto,'maxlength="120" rows="4"')}${area('footerQuote','FOOTER QUOTE',value.footerQuote||DEFAULT_UI_TEXT.footerQuote,'maxlength="180" rows="2"')}<div class="actions"><button class="button primary" type="submit">SAVE</button>${button('RESET TO DEFAULT','ui-text-reset')}</div></form><p class="micro muted">Saved only to the current local profile.</p>`}
export function settingsView(){return `<div class="settings-tabs">${profileSwitcher()}</div><hr>${personalUiText()}<hr><h3>隐私 / 本地数据</h3>${privacySettings()}<hr><div class="actions">${button('切换动效','effects')}${button('DELETE ALL LOCAL PROFILES','profiles-delete-all','','danger')}</div><p class="micro muted">No analytics · No telemetry · No cloud user database</p>`}
export function importOptions(name){return `<p>Backup: <b>${esc(name)}</b></p><p>Only the current local profile will be changed.</p><div class="actions">${button('MERGE（推荐）','backup-import','data-mode="merge"','primary')}${button('REPLACE CURRENT PROFILE','backup-replace','','danger')}${button('CANCEL','close')}</div>`}
